let d1 = if judgment.adjustStatus == "流程已闭环" { 0.0 } else if judgment.adjustStatus == "无需调账" { 0.0 } else if judgment.adjustStatus == "调账处理中" { 20.0 } else { 35.0 };
let d2 = if judgment.evidenceState == "证据完整" { 0.0 } else if judgment.evidenceState == "关键证据完整" { 10.0 } else { 40.0 };
let s = 100.0 - d1 - d2;
if s < 0.0 { 0.0 } else { s }
